import{_ as a,o,c as s,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Estaciones","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station/stations.md","filePath":"es/repair-station/stations.md"}'),i={name:"es/repair-station/stations.md"};function n(l,e,c,t,d,p){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="estaciones" tabindex="-1">Estaciones <a class="header-anchor" href="#estaciones" aria-label="Permalink to &quot;Estaciones&quot;">​</a></h1><p>Una estación es una zona de parada para vehículos, con un radio, un porcentaje de precio y, si quieres, un prop como un cajón de herramientas colocado al lado. Tres estaciones vienen listas: <strong>Hayes Autos</strong>, <strong>Sandy Shores</strong> y <strong>Paleto Bay</strong>.</p><h2 id="como-va-una-reparacion" tabindex="-1">Cómo va una reparación <a class="header-anchor" href="#como-va-una-reparacion" aria-label="Permalink to &quot;Cómo va una reparación&quot;">​</a></h2><ol><li>El conductor se detiene dentro del radio de la estación. Un aviso muestra el precio más bajo.</li><li><strong>E</strong> abre el menú de reparación con los daños del vehículo y los servicios, con sus precios (descuentos por trabajo y porcentaje de la estación incluidos).</li><li>Se paga el precio, el motor se apaga y el capó se abre. Una barra de progreso avanza durante el servicio, con sonido y chispas. Pulsa <strong>X</strong> para cancelar.</li><li>Al terminar, las partes reparadas quedan arregladas y el vehículo puede salir.</li></ol><p>La estación rechaza la reparación cuando:</p><ul><li>la estación está cerrada, o <code>Enabled</code> está desactivado;</li><li>el jugador no conduce el vehículo, o el vehículo no está en la zona de la estación;</li><li>el vehículo se mueve;</li><li>la estación ya está en uso (un vehículo a la vez);</li><li>la clase del vehículo está bloqueada (<code>BlockedClasses</code>);</li><li>el servicio no repara nada en este vehículo y <code>RequireDamage</code> está activado;</li><li>el jugador debe esperar el tiempo de espera (<code>CooldownSeconds</code>);</li><li>hay mecánicos de servicio, ver más abajo;</li><li>el jugador no puede pagar.</li></ul><p>Si el jugador sale del vehículo, se aleja o cancela, o si la estación se cierra o se elimina durante la reparación, la reparación se detiene y se reembolsa al jugador lo cobrado, en la cuenta cobrada.</p><h2 id="mecanicos-de-servicio" tabindex="-1">Mecánicos de servicio <a class="header-anchor" href="#mecanicos-de-servicio" aria-label="Permalink to &quot;Mecánicos de servicio&quot;">​</a></h2><p>Los jugadores que llevan un taller no deben perder clientes frente a una estación. Indica sus trabajos en <code>MechanicJobs</code> y ajusta <code>MaxMechanicsOnDuty</code>: mientras haya ese número de mecánicos o más de servicio, todas las estaciones están cerradas y piden a los jugadores que los llamen. Con <code>0</code>, las estaciones nunca se cierran por este motivo.</p><h2 id="el-editor-de-estaciones" tabindex="-1">El editor de estaciones <a class="header-anchor" href="#el-editor-de-estaciones" aria-label="Permalink to &quot;El editor de estaciones&quot;">​</a></h2><p>Ábrelo con <code>/nay:repair</code>, o con <strong>Gestionar estaciones</strong> en la página Repair Station de <code>/nay</code>. Requiere el scope <code>nay_repair.config</code>.</p><ol><li><strong>Nueva estación aquí</strong>: colócate donde deban detenerse los vehículos, en tu vehículo o a pie. La estación toma tu posición y tu orientación.</li><li>Elige la posición del vehículo o la del prop y muévela: <ul><li>flechas: adelante, atrás, izquierda, derecha, según la cámara;</li><li>Page Up / Page Down: altura;</li><li>Q / E: rotar;</li><li>Mayús: pasos finos.</li></ul></li><li><strong>A mi posición</strong> y <strong>Al suelo</strong> colocan el elemento seleccionado.</li><li>Ajusta el nombre, el radio, el porcentaje de precio, el blip y el prop. Props sugeridos: <code>prop_toolchest_05</code>, <code>prop_toolchest_01</code>, <code>prop_carcreeper</code>, <code>prop_compressor_03</code>, o cualquier nombre de modelo.</li><li><strong>Intro</strong> guarda, <strong>Retroceso</strong> cancela. La estación está activa para todos los jugadores al instante.</li></ol><p>El gestor también permite ir a una estación, abrirla o cerrarla y eliminarla (pulsa dos veces para confirmar). El editor rellena el ajuste <code>Stations</code>, descrito en la página <a href="/es/repair-station/settings#stations">Ajustes</a>. Cada estación recibe un identificador que nunca cambia.</p>',13)])])}const g=a(i,[["render",n]]);export{m as __pageData,g as default};
